async function witnessReader(generation = 1, source = { start(c) { c.close(); } }) {
  const storage = new AsyncLocalStorage(), owner = litellmOwnership(storage, generation), acquisition = {};
  const response = new Response(new ReadableStream(source)), caller = new AbortController(), guard = new AbortController(), native = new AbortController();
  let context, reader;
  await owner.invoke({ id: "sdk_eof", role: "chat", api: "streamSimple", signal: caller.signal, url: "https://fixture.example/chat", credential: "fixture" }, () =>
    owner.guard("chat", async () => {
      context = storage.getStore();
      const pending = owner.fetch(() => Promise.resolve(response), undefined, [], { url: "https://fixture.example/chat", method: "POST", credential: "fixture", signal: native.signal });
      await pending; owner.attach(acquisition, { response }); reader = response.body.getReader(); owner.reader(response.body, reader, response.body);
      owner.witness.closed(reader, reader.closed);
    }, undefined, [{ signal: guard.signal }], acquisition), undefined, [{}, {}, { signal: caller.signal }]);
  return { owner, storage, context, reader, response, acquisition, caller, guard, native };
}
