function reportingParts(id = "sdk_provider_error", max = false) {
  const parts = [
    { at: "original_drain", body: "fulfilled", caseId: id, role: "chat", control: "provider_error", api: "streamSimple", ids: [1, 1, 1, 1], g: [4, 4, 80], op: "read", pred: "none", ctx: ["same", true, true, true, true, true, 4, true], time: [25, 26, 53, 1, 0], life: [46, 49, 54, 55, 58, 1, 1], counts: [18, 0, 15, 3], failures: 0, source: "unknown", reaction: null },
    { ids: [1, 1, 1, 1], acquisition: null, originals: [[5, "rejected", 25, 26, 53, true, "object", false, true, true], [4, "rejected", 20, 21, 52, true, "object", false, true, true], [7, "rejected", 45, 47, 51, true, "object", false, true, true]], same: [true, true, true], signals: [[false, true, true], [false, true, true], [false, true, true]], cancel: ["undefined", false, false, false], input: [[false, null, 0], [false, null, 0], [false, null, 0]], output: [[false, null, 0], [true, "object", 44], [true, "object", 43]], release: "fulfilled", locked: false, eof: false, otherRejected: 0, abortOperand: "unknown" },
  ];
  if (max) {
    const widen = v => Array.isArray(v) ? v.map(widen) : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, widen(x)])) : typeof v === "number" ? 1_000_000 : typeof v === "boolean" ? false : v;
    const full = widen(parts);
    full[0].at = "dispatcher_destroyed"; full[0].op = "guard_acquisition"; full[0].pred = "reader_duplicate"; full[0].ctx[0] = "unrecognized";
    const original = [1_000_000, "sync_throw", 1_000_000, 1_000_000, 1_000_000, false, "undefined", false, false, false];
    full[1].acquisition = [...original]; full[1].originals = Array.from({ length: 3 }, () => [...original]);
    full[1].input = full[1].output = Array.from({ length: 3 }, () => [false, "undefined", 1_000_000]); full[1].release = "sync_throw";
    return full;
  }
  return parts;
}
function reportingPair(proof, id = "sdk_provider_error", select = [true, false], max = false) {
  return proof.witness(proof.record("sdk", id, "join", undefined, "chat"), select, reportingParts(id, max));
}
function reportingDecode(proof, lines) {
  return lines.map(line => { assert.ok(line.startsWith("::error title=LiteLLM typed contract::")); assert.ok(Buffer.byteLength(line) <= 768); const r = proof.validate(JSON.parse(line.slice("::error title=LiteLLM typed contract::".length))); assert.ok(r); return r; });
}
function reportingLeaves(value) {
  return value instanceof AggregateError ? value.errors.flatMap(reportingLeaves) : [value];
}

